/*
 * Declarations of the stock libbzip2 1.0.8 functions under the ref_ prefix
 * (reference_rename.h), for tests and benchmarks that link the reference next
 * to bz2-ng, and of the randomising compressor's entry point (rand_ prefix;
 * generated by test/CMakeLists.txt).  They are declared with BZ_API because
 * bzlib.c defines them with it: on Windows that is WINAPI, which on 32-bit
 * x86 is a different calling convention and a decorated symbol name.
 *
 * Part of bz2-ng; MIT licence (see LICENSE).
 */
#ifndef TEST_REFERENCE_API_H
#define TEST_REFERENCE_API_H

#include <stdio.h>

#include "bzlib.h"

int BZ_API(ref_BZ2_bzCompressInit)(bz_stream *strm, int blockSize100k,
				   int verbosity, int workFactor);
int BZ_API(ref_BZ2_bzCompress)(bz_stream *strm, int action);
int BZ_API(ref_BZ2_bzCompressEnd)(bz_stream *strm);
int BZ_API(ref_BZ2_bzDecompressInit)(bz_stream *strm, int verbosity, int small);
int BZ_API(ref_BZ2_bzDecompress)(bz_stream *strm);
int BZ_API(ref_BZ2_bzDecompressEnd)(bz_stream *strm);
int BZ_API(ref_BZ2_bzBuffToBuffCompress)(char *dest, unsigned int *destLen,
					 char *source, unsigned int sourceLen,
					 int blockSize100k, int verbosity,
					 int workFactor);
int BZ_API(ref_BZ2_bzBuffToBuffDecompress)(char *dest, unsigned int *destLen,
					   char *source, unsigned int sourceLen,
					   int small, int verbosity);
BZFILE *BZ_API(ref_BZ2_bzWriteOpen)(int *bzerror, FILE *f, int blockSize100k,
				    int verbosity, int workFactor);
void BZ_API(ref_BZ2_bzWrite)(int *bzerror, BZFILE *b, void *buf, int len);
void BZ_API(ref_BZ2_bzWriteClose64)(int *bzerror, BZFILE *b, int abandon,
				    unsigned int *nbytes_in_lo32,
				    unsigned int *nbytes_in_hi32,
				    unsigned int *nbytes_out_lo32,
				    unsigned int *nbytes_out_hi32);
BZFILE *BZ_API(ref_BZ2_bzReadOpen)(int *bzerror, FILE *f, int verbosity,
				   int small, void *unused, int nUnused);
void BZ_API(ref_BZ2_bzReadClose)(int *bzerror, BZFILE *b);
void BZ_API(ref_BZ2_bzReadGetUnused)(int *bzerror, BZFILE *b, void **unused,
				     int *nUnused);
int BZ_API(ref_BZ2_bzRead)(int *bzerror, BZFILE *b, void *buf, int len);

int BZ_API(rand_BZ2_bzBuffToBuffCompress)(char *dest, unsigned int *destLen,
					  char *source, unsigned int sourceLen,
					  int blockSize100k, int verbosity,
					  int workFactor);

#endif /* TEST_REFERENCE_API_H */
